const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define lake geometries (Ethiopia, approximate coordinates)
  const langanoGeo = ee.Geometry.Point([38.75, 8.95]).buffer(5000);
  const abijataGeo = ee.Geometry.Point([39.50, 8.25]).buffer(5000);

  // 2. Date range around March 29, 2022
  const startDate = '2022-03-24';
  const endDate = '2022-04-03';

  // 3. Sentinel-2 data with cloud mask
  let langanoCol = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(langanoGeo)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  let abijataCol = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(abijataGeo)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const langanoSize = await langanoCol.size().getInfo();
  const abijataSize = await abijataCol.size().getInfo();

  // 4. Check for data availability
  if (langanoSize === 0 || abijataSize === 0) {
    console.log(`Langano Images: ${langanoSize}, Abijata Images: ${abijataSize}`);
    console.log('C1');
    return;
  }

  // 5. Prepare images (median composite)
  const langanoImg = langanoCol.median();
  const abijataImg = abijataCol.median();

  // 6. Calculate brownness using red band (B4) as proxy
  // Higher red band value = more sediment/brown
  const langanoRed = langanoImg.select('B4');
  const abijataRed = abijataImg.select('B4');

  // 7. Calculate mean red value (brownness metric)
  const langanoStats = await langanoRed.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: langanoGeo,
    scale: 10,
    maxPixels: 1e9
  }).getInfo();

  const abijataStats = await abijataRed.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: abijataGeo,
    scale: 10,
    maxPixels: 1e9
  }).getInfo();

  const langanoMean = langanoStats['B4_mean'];
  const abijataMean = abijataStats['B4_mean'];
  const langanoCount = langanoStats['B4_count'];
  const abijataCount = abijataStats['B4_count'];

  // 8. Validate pixel counts
  if (langanoCount === 0 || abijataCount === 0) {
    console.log(`Langano Valid Pixels: ${langanoCount}, Abijata Valid Pixels: ${abijataCount}`);
    console.log('C2');
    return;
  }

  // 9. Validate results
  if (langanoMean === null || abijataMean === null || 
      isNaN(langanoMean) || isNaN(abijataMean)) {
    console.log('C3');
    return;
  }

  // 10. Compare brownness
  console.log(`Langano Images: ${langanoSize}, Red Mean: ${langanoMean.toFixed(2)}, Pixels: ${langanoCount}`);
  console.log(`Abijata Images: ${abijataSize}, Red Mean: ${abijataMean.toFixed(2)}, Pixels: ${abijataCount}`);
  console.log(`Langano Red > Abijata Red: ${langanoMean > abijataMean}`);

  if (langanoMean > abijataMean) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
